DROP TABLE IF EXISTS `sys_role`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `role_code` varchar(64) NOT NULL COMMENT '角色编码',
  `role_name` varchar(100) NOT NULL COMMENT '角色名称',
  `data_scope` tinyint NOT NULL DEFAULT '5' COMMENT '数据权限:1本租户全部 2本公司 3本部门及以下 4本部门 5仅本人 6自定义(见sys_role_dept)',
  `org_scope` varchar(20) NOT NULL DEFAULT 'COMPANY' COMMENT '组织范围：COMPANY=本公司内解析(业务审批段)/GROUP=跨公司(共享段+集团垂直)',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `is_builtin` tinyint NOT NULL DEFAULT '0' COMMENT '是否内置角色:0否 1是(内置角色不可删)',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL正常/DISABLED停用',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_role_code` (`tenant_id`,`role_code`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=99884 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='角色';
